int main() {
    int choix;
    int essais = 0;
    return 0;
}

solution:
#include <iostream>

int main() {
    int choix;
    int essais = 0;
    do {
        std::cin >> choix;
        essais++;
    } while (choix < 1 || choix > 3);
    int montant;
    std::cin >> montant;
    switch (choix) {
        case 1: std::cout << "Dépôt : " << montant << " FCFA\n"; break;
        case 2: std::cout << "Retrait : " << montant << " FCFA\n"; break;
        case 3: std::cout << "Frais : " << montant / 100 << " FCFA\n"; break;
    }
    std::cout << "Essais : " << essais << "\n";
    return 0;
}
